import Foundation
import XCTest
@testable import MonsteraRuntime

/// Conformance tests: contract vectors plus every golden scenario recorded by the oracle.
/// Set MONSTERA_CONFORMANCE_OUT to a file path to also receive one JSON line per checkpoint.
final class ConformanceTests: XCTestCase {
    func testFixedPointVectors() {
        XCTAssertEqual(Fx.mul(-1, 1), -1)
        XCTAssertEqual(Fx.mul(Fx.rawMax, Fx.rawMax), Fx.rawMax)
        XCTAssertEqual(Fx.mul(Fx.rawMin, Fx.rawMin), Fx.rawMax)
        XCTAssertEqual(Fx.mul(-3, 32768), -2)
        XCTAssertEqual(Fx.mul(3, -32768), -2)
        XCTAssertEqual(Fx.div(65536, 196608), 21845)
        XCTAssertEqual(Fx.div(-65536, 196608), -21845)
        XCTAssertEqual(Fx.div(65536, -196608), -21845)
        XCTAssertEqual(Fx.div(5, 0), Fx.rawMax)
        XCTAssertEqual(Fx.div(-5, 0), Fx.rawMin)
        XCTAssertEqual(Fx.div(0, 0), 0)
        XCTAssertEqual(Fx.div(Fx.rawMin, -1), Fx.rawMax)
        XCTAssertEqual(Fx.neg(Fx.rawMin), Fx.rawMax)
        XCTAssertEqual(Fx.add(Fx.rawMax, 1), Fx.rawMax)
        XCTAssertEqual(Fx.sub(Fx.rawMin, 1), Fx.rawMin)
    }

    func testRandomnessVectors() {
        var ref = Pcg32(initstate: 42, initseq: 54)
        XCTAssertEqual((0..<6).map { _ in ref.nextU32() },
                       [0xa15c02b7, 0x7b47f409, 0xba1d3330, 0x83d2f293, 0xbfa4784b, 0xcbed606e])
        XCTAssertEqual(fnv1a64(Array("foobar".utf8)), 0x85944171f73967e8)
        XCTAssertEqual(fnv1a64(Array("a".utf8)), 0xaf63dc4c8601ec8c)

        var spawn = Pcg32(seed: 12345, stream: "spawn")
        XCTAssertEqual((0..<4).map { _ in spawn.nextU32() }, [3836204951, 2901556457, 1288830458, 20171900])
        XCTAssertEqual(spawn.state, 0xbe81daf6f5b5d3bb)
        XCTAssertEqual(spawn.inc, 0x6f4a8582f6e4629f)

        var fx = Pcg32(seed: 12345, stream: "fx")
        XCTAssertEqual((0..<4).map { _ in fx.nextU32() }, [3544770967, 1588508108, 78643710, 1025764217])

        var bounded = Pcg32(seed: 1, stream: "spawn")
        XCTAssertEqual((0..<8).map { _ in bounded.nextBelow(10) }, [6, 0, 2, 2, 1, 0, 3, 7])
        XCTAssertEqual([bounded.nextBelow(1), bounded.nextBelow(1)], [0, 0])
        XCTAssertEqual(bounded.nextBelow(1 << 31), 1771058001)
    }

    private struct Scenario {
        let name: String
        let seed: UInt64
        let ticks: Int
        var inputs: [TickInput] = []
        var expected: [Checkpoint] = []
    }

    private func parseScenarios() throws -> [Scenario] {
        guard let url = Bundle.module.url(forResource: "monstera-scenarios", withExtension: "txt") else {
            XCTFail("monstera-scenarios.txt is missing from the test resources")
            return []
        }
        let text = try String(contentsOf: url, encoding: .utf8)
        var out: [Scenario] = []
        var current: Scenario?
        for line in text.split(separator: "\n", omittingEmptySubsequences: true) {
            if line.hasPrefix("#") || line.hasPrefix("monstera-scenarios ") { continue }
            let p = line.split(separator: " ").map(String.init)
            switch p[0] {
            case "scenario":
                current = Scenario(name: p[1], seed: UInt64(p[2])!, ticks: Int(p[3])!)
            case "input":
                let types: [String: InputType] = ["press": .press, "release": .release, "tap": .tap, "drag": .drag, "swipe": .swipe]
                let dirs: [String: Direction] = ["none": .none, "up": .up, "down": .down, "left": .left, "right": .right]
                let event = InputEvent(types[p[2]]!, dx: Int64(p[3])!, dy: Int64(p[4])!, dir: dirs[p[5]]!)
                let tick = Int(p[1])!
                if let last = current!.inputs.last, last.tick == tick {
                    current!.inputs[current!.inputs.count - 1] = TickInput(tick: tick, events: last.events + [event])
                } else {
                    current!.inputs.append(TickInput(tick: tick, events: [event]))
                }
            case "checkpoint":
                current!.expected.append(Checkpoint(tick: Int(p[1])!, hash: UInt64(p[2], radix: 16)!,
                                                    observe: p[3...8].map { Int64($0)! }))
            case "end":
                out.append(current!)
                current = nil
            default:
                XCTFail("unknown line: \(line)")
            }
        }
        return out
    }

    private func hex(_ h: UInt64) -> String {
        let s = String(h, radix: 16)
        return String(repeating: "0", count: 16 - s.count) + s
    }

    func testGoldenScenarios() throws {
        let scenarios = try parseScenarios()
        XCTAssertFalse(scenarios.isEmpty, "no scenarios found")
        var lines: [String] = []
        var failures: [String] = []
        for sc in scenarios {
            let got = replay(config: GeneratedRuntimeConfig.config, seed: sc.seed, ticks: sc.ticks,
                             inputs: sc.inputs, checkpointTicks: sc.expected.map { $0.tick })
            for g in got {
                lines.append("{\"platform\":\"swift\",\"scenario\":\"\(sc.name)\",\"tick\":\(g.tick),\"hash\":\"\(hex(g.hash))\","
                             + "\"observe\":[\(g.observe.map { String($0) }.joined(separator: ","))]}")
            }
            if let bad = zip(sc.expected, got).first(where: { $0 != $1 }) {
                let fields = observableNames.indices.filter { bad.0.observe[$0] != bad.1.observe[$0] }
                    .map { observableNames[$0] }.joined(separator: ", ")
                failures.append("\(sc.name): first divergence at tick \(bad.0.tick) (hash \(hex(bad.0.hash)) vs \(hex(bad.1.hash)); fields: \(fields.isEmpty ? "hash only" : fields))")
            } else if got.count != sc.expected.count {
                failures.append("\(sc.name): produced \(got.count) checkpoints, expected \(sc.expected.count)")
            }
        }
        if let path = ProcessInfo.processInfo.environment["MONSTERA_CONFORMANCE_OUT"] {
            try (lines.joined(separator: "\n") + "\n").write(toFile: path, atomically: true, encoding: .utf8)
        }
        XCTAssertTrue(failures.isEmpty, failures.joined(separator: "\n"))
    }
}
